const button=document.getElementById('menu-toggle');
const overlay=document.getElementById('overlay');
function setMenu(open){document.body.classList.toggle('menu-open',open);button?.setAttribute('aria-expanded',String(open));overlay.hidden=!open;if(!open)button?.focus();}
button?.addEventListener('click',()=>setMenu(!document.body.classList.contains('menu-open')));
overlay?.addEventListener('click',()=>setMenu(false));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('menu-open'))setMenu(false)});
document.querySelectorAll('[data-print]').forEach(b=>b.addEventListener('click',()=>window.print()));

// Preserve shared concept links and reveal targets inside collapsed examples.
let highlightedTarget;
let highlightTimer;
function revealTarget(){
  const id=decodeURIComponent(location.hash.slice(1));
  if(!id)return;
  const anchor=document.getElementById(id);
  if(!anchor)return;
  // Concept markers precede an existing paragraph, table, list or diagram.
  const target=anchor.hasAttribute('data-plan-target') ? anchor.nextElementSibling : anchor;
  if(!target)return;
  let element=target;
  while(element){if(element.tagName==='DETAILS')element.open=true;element=element.parentElement;}
  clearTimeout(highlightTimer);
  highlightedTarget?.classList.remove('plan-highlight');
  requestAnimationFrame(()=>{
    target.scrollIntoView({block:'start',behavior:'instant'});
    if(anchor.hasAttribute('data-plan-target')){
      target.classList.add('plan-highlight');
      target.setAttribute('tabindex','-1');
      target.focus({preventScroll:true});
      highlightedTarget=target;
      highlightTimer=setTimeout(()=>target.classList.remove('plan-highlight'),4500);
    }
  });
}
window.addEventListener('hashchange',revealTarget);
if(location.hash)revealTarget();

// Keep the original diagram and show one explanation below it.
document.querySelectorAll('[data-workflow-diagram]').forEach(diagram=>{
  const targets=diagram.querySelectorAll('[data-workflow-step]');
  const panels=diagram.querySelectorAll('[data-workflow-panel]');
  const description=diagram.querySelector('.workflow-description');
  targets.forEach(target=>target.addEventListener('click',()=>{
    targets.forEach(item=>item.setAttribute('aria-pressed',String(item===target)));
    panels.forEach(panel=>{panel.hidden=panel.dataset.workflowPanel!==target.dataset.workflowStep;});
    description.setAttribute('aria-labelledby',target.id);
  }));
});

